function executeSkill(context) {
      var world = battle.extensions.adventureWorld, plan = world.plans && world.plans[0];
      var mark = plan && plan.kind === 'summon' && plan.cells[0];
      if (!mark || plan.sourceId !== context.piece.instanceId || plan.round !== world.party.battleRound) return {success:false,message:'没有召唤预告'};
      if (battle.pieces.some(function(p){return p.currentHp > 0 && (p.templateId === 'pve-ghoul' || (p.x===mark.x && p.y===mark.y));})) return {success:false,message:'墓印被占据或食尸鬼仍在场'};
      context.summonQueue.push({summons:[{x:mark.x,y:mark.y}],sourceId:context.piece.instanceId});
      return {success:true,message:'亡者复生'};
    }
